import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.Bxhvufce.js";const m=JSON.parse('{"title":"Package Management with OmniGet (og)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/Package-Management-with-OmniGet.md","filePath":"guides/Package-Management-with-OmniGet.md"}'),l={name:"guides/Package-Management-with-OmniGet.md"};function n(s,e,r,d,c,g){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="package-management-with-omniget-og" tabindex="-1">Package Management with OmniGet (og) <a class="header-anchor" href="#package-management-with-omniget-og" aria-label="Permalink to &quot;Package Management with OmniGet (og)&quot;">​</a></h1><p><strong>Windows CoreOS (WCOS)</strong> integrates <strong>OmniGet (<code>og</code>)</strong> as its official, multi-source package manager. OmniGet is designed specifically for headless Windows environments, zero-touch CI/CD pipelines, and autonomous AI agents.</p><hr><h2 id="🛍️-what-is-omniget" tabindex="-1">🛍️ What is OmniGet? <a class="header-anchor" href="#🛍️-what-is-omniget" aria-label="Permalink to &quot;🛍️ What is OmniGet?&quot;">​</a></h2><p><a href="https://github.com/samuelcaldas/omniget" target="_blank" rel="noreferrer">OmniGet</a> is a lightweight, universal package management engine implemented in PowerShell 7 Core. It provides:</p><ul><li><strong>5 Package Providers</strong>: Ninite dynamic bundling, GitHub Releases, Direct Vendor installers, Distro Recipes, and NPM.</li><li><strong>Hot-Swap In-Use Binary Replacement</strong>: Updates locked executables and running services without kicking active users or killing SSH sessions.</li><li><strong>Zero-Reboot Windows Installer Suppression</strong>: Bypasses Windows Restart Manager prompts (<code>MSIRESTARTMANAGERCONTROL=Disable</code>).</li><li><strong>Interactive ANSI TUI</strong>: Full-screen arrow-key navigation interface and searchable package directory.</li><li><strong>Standardized Path Placement</strong>: Enforces enterprise filesystem standards (<code>C:\\Program Files\\&lt;App&gt;</code>), strictly prohibiting cluttered root <code>C:\\</code> directories.</li></ul><hr><h2 id="⚡-omniget-cli-quick-reference" tabindex="-1">⚡ OmniGet CLI Quick Reference <a class="header-anchor" href="#⚡-omniget-cli-quick-reference" aria-label="Permalink to &quot;⚡ OmniGet CLI Quick Reference&quot;">​</a></h2><p>OmniGet is available globally on the system <code>PATH</code> via <code>og</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Example</th></tr></thead><tbody><tr><td style="text-align:left;"><code>og search &lt;query&gt;</code></td><td style="text-align:left;">Search available packages across all providers</td><td style="text-align:left;"><code>og search git</code></td></tr><tr><td style="text-align:left;"><code>og install &lt;app&gt;</code></td><td style="text-align:left;">Silently install an application</td><td style="text-align:left;"><code>og install python</code></td></tr><tr><td style="text-align:left;"><code>og update &lt;app&gt;</code></td><td style="text-align:left;">Hot-swap upgrade application safely</td><td style="text-align:left;"><code>og update pwsh</code></td></tr><tr><td style="text-align:left;"><code>og upgrade</code></td><td style="text-align:left;">Update all installed packages</td><td style="text-align:left;"><code>og upgrade</code></td></tr><tr><td style="text-align:left;"><code>og preset &lt;name&gt;</code></td><td style="text-align:left;">Install curated stack bundle</td><td style="text-align:left;"><code>og preset DevStack</code></td></tr><tr><td style="text-align:left;"><code>og list</code></td><td style="text-align:left;">List installed applications and versions</td><td style="text-align:left;"><code>og list</code></td></tr><tr><td style="text-align:left;"><code>og info &lt;app&gt;</code></td><td style="text-align:left;">Display detailed package metadata</td><td style="text-align:left;"><code>og info node</code></td></tr><tr><td style="text-align:left;"><code>og</code></td><td style="text-align:left;">Launch interactive terminal UI (TUI)</td><td style="text-align:left;"><code>og</code></td></tr></tbody></table><hr><h2 id="📦-available-presets" tabindex="-1">📦 Available Presets <a class="header-anchor" href="#📦-available-presets" aria-label="Permalink to &quot;📦 Available Presets&quot;">​</a></h2><p>WCOS comes with pre-configured software stacks that can be installed with a single command:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">og preset DevStack</span></span></code></pre></div><ul><li><strong><code>DevStack</code></strong>: Complete developer environment (Git, GitHub CLI, Node.js LTS, Python 3.12, .NET SDK, Docker CLI).</li><li><strong><code>Browsers</code></strong>: Google Chrome, Mozilla Firefox, Microsoft Edge.</li><li><strong><code>Minimal</code></strong>: Lightweight essentials (7-Zip, Notepad++, Git, PowerShell 7).</li><li><strong><code>Utilities</code></strong>: System administration tools (Process Hacker, Sysinternals Suite, Everything).</li><li><strong><code>SystemShells</code></strong>: WinXShell desktop environment, Microsoft WinFile, WezTerm.</li><li><strong><code>AIStack</code></strong>: Google Antigravity CLI, Anthropic Claude Code CLI, OpenAI Codex CLI.</li></ul><hr><h2 id="🔄-zero-downtime-hot-swap-upgrades" tabindex="-1">🔄 Zero-Downtime Hot-Swap Upgrades <a class="header-anchor" href="#🔄-zero-downtime-hot-swap-upgrades" aria-label="Permalink to &quot;🔄 Zero-Downtime Hot-Swap Upgrades&quot;">​</a></h2><p>A major pain point in standard Windows administration is that running executables (such as <code>pwsh.exe</code> during an SSH session) cannot be overwritten because Windows locks open files (<code>ERROR_SHARING_VIOLATION</code>).</p><p>OmniGet implements atomic in-use rotation:</p><ol><li>Detects if target executable <code>target.exe</code> is locked by a running process.</li><li>Moves locked binary to <code>target.exe.old_&lt;timestamp&gt;</code>. (Windows allows renaming running executables).</li><li>Writes the new binary into the destination path.</li><li>Registers <code>MoveFileExW</code> with <code>MOVEFILE_DELAY_UNTIL_REBOOT</code> to remove the <code>.old</code> file on next system start.</li><li>Suppresses MSI reboots using <code>REBOOT=ReallySuppress</code> and <code>MSIRESTARTMANAGERCONTROL=Disable</code>.</li></ol><p>This allows upgrading PowerShell 7 or Git live over SSH without losing the terminal session!</p><hr><h2 id="📁-filesystem-installation-directory-standard" tabindex="-1">📁 Filesystem &amp; Installation Directory Standard <a class="header-anchor" href="#📁-filesystem-installation-directory-standard" aria-label="Permalink to &quot;📁 Filesystem &amp; Installation Directory Standard&quot;">​</a></h2><p>OmniGet enforces strict adherence to Windows enterprise directory standards:</p><ul><li><strong>64-bit Applications</strong>: Installed strictly under <code>C:\\Program Files\\&lt;VendorOrToolName&gt;</code> (e.g., <code>C:\\Program Files\\Git</code>, <code>C:\\Program Files\\nodejs</code>, <code>C:\\Program Files\\OmniGet</code>).</li><li><strong>32-bit Applications</strong>: Installed under <code>C:\\Program Files (x86)\\&lt;VendorOrToolName&gt;</code>.</li><li><strong>Global System State &amp; Databases</strong>: Reside in <code>C:\\ProgramData\\OmniGet</code>.</li><li><strong>User Data &amp; Configurations</strong>: Reside in <code>%APPDATA%</code> or <code>%USERPROFILE%\\.&lt;tool&gt;</code>.</li><li><strong>Strict Prohibition of Root <code>C:\\</code> Directories</strong>: Applications are NEVER installed directly to <code>C:\\</code> (e.g. <code>C:\\Tools</code>, <code>C:\\Python</code> are forbidden).</li></ul>',25)])])}const h=t(l,[["render",n]]);export{m as __pageData,h as default};
